#include "knn.h"
#include <math.h>
#include <stdlib.h>
#include <string.h>

double distance(const double *a,const double *b,int count,Metric metric){double total=0,dot=0,aa=0,bb=0;for(int j=0;j<count;j++){double x=a[j],y=b[j],d=x-y;if(metric==SQUARED_EUCLIDEAN)total+=d*d;else if(metric==MANHATTAN)total+=fabs(d);else if(metric==CHEBYSHEV)total=fmax(total,fabs(d));else{dot+=x*y;aa+=x*x;bb+=y*y;}}if(metric==COSINE){double na=sqrt(aa),nb=sqrt(bb);if(na==0||nb==0)return 1;return 1-dot/(na*nb);}return total;}
static int compare_neighbors(const void *left,const void *right){const Neighbor *a=left,*b=right;if(a->distance!=b->distance)return a->distance<b->distance?-1:1;return strcmp(a->row->id,b->row->id);}
void sort_neighbors(Neighbor *order,int count){if(count>1)qsort(order,(size_t)count,sizeof *order,compare_neighbors);}
void neighbor_order(const double *query,const Rows *rows,const double *vectors,int width,Metric metric,Neighbor *order){for(int j=0;j<rows->count;j++)order[j]=(Neighbor){rows->values[j],distance(query,vectors+j*width,width,metric)};sort_neighbors(order,rows->count);}
static bool tally_before(int a,int b,Weighting weighting,const int *counts,const double *distances,const double *weights){if(weighting==UNIFORM){if(counts[a]!=counts[b])return counts[a]>counts[b];}else if(weights[a]!=weights[b])return weights[a]>weights[b];if(distances[a]!=distances[b])return distances[a]<distances[b];return a<b;}
Prediction predict_order(const Neighbor *order,int count,int k,Weighting weighting){if(k>count)k=count;int counts[MAX_CLASSES]={0},labels[25],label_count=0;double distances[MAX_CLASSES]={0},weights[MAX_CLASSES]={0},weight_total=0,targets=0,weighted=0;for(int j=0;j<k;j++){Neighbor n=order[j];int label=n.row->label_index;double w=1/(n.distance+0.000000001);if(!counts[label])labels[label_count++]=label;counts[label]++;distances[label]+=n.distance;weights[label]+=w;weight_total+=w;targets+=n.row->target;weighted+=w*n.row->target;}for(int j=1;j<label_count;j++){int value=labels[j],position=j;while(position>0&&tally_before(value,labels[position-1],weighting,counts,distances,weights)){labels[position]=labels[position-1];position--;}labels[position]=value;}Prediction p={.label=labels[0],.runner=-1,.share=weighting==UNIFORM?(double)counts[labels[0]]/k:weights[labels[0]]/weight_total,.estimate=weighting==UNIFORM?targets/k:weighted/weight_total};if(label_count>1){p.runner=labels[1];p.runner_share=weighting==UNIFORM?(double)counts[labels[1]]/k:weights[labels[1]]/weight_total;}return p;}
